-- NV: 151 researched stops.
--
-- 147 new, 4 updating a row already in the index.
-- After running this and scripts/refresh-site.mts, /explore should read
-- 6179.
--
-- Coordinates are deliberately NOT updated on conflict: a checked position
-- must never be replaced by an unchecked one. Where the existing row came
-- from the OpenStreetMap scan and is wrong by a kilometre, delete that slug
-- first and let this insert instead.
--
-- state is deliberately NOT updated either. That is how an overwritten stop
-- in another state keeps its old state and hides — so the collision check
-- above refuses rather than relying on anyone noticing afterwards.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, timezone)
values
  ('The Neon Museum', 'the-neon-museum', 'museums', 36.17669, -115.13521, 'Las Vegas', 'NV', 'The Boneyard preserves hundreds of rescued Las Vegas signs, turning the city’s discarded neon into an outdoor museum of casino, motel, and roadside history.', 'limited', 'https://www.neonmuseum.org/', 'America/Los_Angeles'),
  ('Atomic Museum', 'atomic-museum', 'weird-history', 36.1141, -115.14834, 'Las Vegas', 'NV', 'Nevada’s official atomic-history museum covers the Nevada Test Site, nuclear testing, Cold War culture, and artifacts tied to the state’s unusual atomic legacy.', 'open', 'https://www.atomicmuseum.vegas/', 'America/Los_Angeles'),
  ('The Mob Museum', 'the-mob-museum', 'weird-history', 36.1728, -115.14127, 'Las Vegas', 'NV', 'Housed in the former federal courthouse, this museum traces organized crime, law enforcement, Prohibition, and the mob’s long connection to Las Vegas.', 'open', 'https://themobmuseum.org/', 'America/Los_Angeles'),
  ('Pinball Hall of Fame', 'pinball-hall-of-fame', 'museums', 36.08486, -115.17171, 'Las Vegas', 'NV', 'A huge playable collection of vintage pinball and arcade machines, including decades of coin-operated oddities that are preserved by a nonprofit museum.', 'open', 'https://www.pinballmuseum.org/', 'America/Los_Angeles'),
  ('Burlesque Hall of Fame', 'burlesque-hall-of-fame', 'museums', 36.16006, -115.15302, 'Las Vegas', 'NV', 'An unusual museum dedicated to the history, costumes, performers, and ephemera of American burlesque.', 'open', 'https://burlesquehall.com/', 'America/Los_Angeles'),
  ('The Punk Rock Museum', 'the-punk-rock-museum', 'museums', 36.15434, -115.16064, 'Las Vegas', 'NV', 'A museum built around punk history, stage gear, handwritten material, clothing, flyers, and artifacts contributed by musicians and scenes from around the world.', 'open', 'https://www.thepunkrockmuseum.com/', 'America/Los_Angeles'),
  ('Erotic Heritage Museum', 'erotic-heritage-museum', 'museums', 36.13008, -115.17469, 'Las Vegas', 'NV', 'A museum examining erotic art, sexuality, social history, and cultural taboos through rotating and permanent exhibits; adults-only policies apply.', 'open', 'https://www.eroticmuseumvegas.com/', 'America/Los_Angeles'),
  ('Titanic: The Artifact Exhibition — Las Vegas', 'titanic-the-artifact-exhibition-las-vegas', 'weird-history', 36.09549, -115.17585, 'Las Vegas', 'NV', 'A large Titanic exhibition at Luxor featuring recovered artifacts, recreated ship spaces, and interpretation of the 1912 disaster.', 'limited', 'https://luxor.mgmresorts.com/en/entertainment/titanic.html', 'America/Los_Angeles'),
  ('Old Las Vegas Mormon Fort State Historic Park', 'old-las-vegas-mormon-fort-state-historic-park', 'weird-history', 36.18057, -115.13347, 'Las Vegas', 'NV', 'The remains of the 1855 adobe fort mark the first permanent non-Indigenous settlement in the Las Vegas Valley, long before the Strip existed.', 'open', 'https://parks.nv.gov/parks/old-las-vegas-mormon-fort', 'America/Los_Angeles'),
  ('Tom Devlin’s Monster Museum', 'tom-devlins-monster-museum', 'museums', 35.97156, -114.85072, 'Boulder City', 'NV', 'A practical-effects museum packed with handmade monsters, masks, props, and creature-making displays from horror-film culture.', 'open', 'https://tomdevlinsmonstermuseum.com/', 'America/Los_Angeles'),
  ('Outpost 51 Alien Museum', 'outpost-51-alien-museum', 'ufos', 35.97093, -114.84954, 'Boulder City', 'NV', 'A compact alien-themed museum and roadside stop devoted to UFO imagery, Nevada extraterrestrial lore, and Area 51 culture.', 'open', 'https://travelnevada.com/museums/outpost-51-alien-museum/', 'America/Los_Angeles'),
  ('Nevada State Railroad Museum — Boulder City', 'nevada-state-railroad-museum-boulder-city', 'weird-history', 35.97063, -114.85646, 'Boulder City', 'NV', 'A working railroad museum on the historic Boulder Branch Line, with preserved equipment and seasonal excursion-train operations.', 'limited', 'https://www.boulderrailroadmuseum.org/', 'America/Los_Angeles'),
  ('Hoover Dam', 'hoover-dam', 'weird-history', 36.0163, -114.7372, 'Boulder City', 'NV', 'The immense Depression-era dam is one of Nevada’s defining feats of engineering, with monumental Art Deco details and a deep layer of construction history.', 'limited', 'https://www.usbr.gov/lc/hooverdam/', 'America/Los_Angeles'),
  ('Historic Railroad Tunnel Trail', 'historic-railroad-tunnel-trail', 'weird-history', 36.01092, -114.79397, 'Boulder City', 'NV', 'This trail follows the old rail grade used during Hoover Dam construction and passes through a chain of oversized railroad tunnels blasted through volcanic rock.', 'open', 'https://www.nps.gov/thingstodo/hike-the-historic-railroad-trail.htm', 'America/Los_Angeles'),
  ('Seven Magic Mountains', 'seven-magic-mountains', 'roadside-oddities', 35.84134, -115.26945, 'Jean', 'NV', 'Ugo Rondinone’s towering stacks of fluorescent boulders rise from the Mojave beside Interstate 15, creating one of Nevada’s most recognizable roadside art stops.', 'open', 'https://sevenmagicmountains.com/', 'America/Los_Angeles'),
  ('Pioneer Saloon', 'pioneer-saloon', 'weird-history', 35.83244, -115.43192, 'Goodsprings', 'NV', 'A 1913 pressed-tin saloon preserves bullet holes, mining-town artifacts, and the local story surrounding Clark Gable’s wait for news after Carole Lombard’s plane crash.', 'open', 'https://pioneersaloonnv.com/', 'America/Los_Angeles'),
  ('Goodsprings Cemetery', 'goodsprings-cemetery', 'weird-history', 35.8295, -115.4278, 'Goodsprings', 'NV', 'A desert cemetery tied to the old mining settlement, with weathered graves and local stories from Goodsprings’ boom-and-bust era; visit respectfully.', 'open', 'https://travelnevada.com/cities/goodsprings/', 'America/Los_Angeles'),
  ('Nelson Ghost Town', 'nelson-ghost-town', 'weird-history', 35.7072, -114.8261, 'Nelson', 'NV', 'The photogenic remains around Nelson preserve the violent mining history of Eldorado Canyon, with old structures, vehicles, mine relics, and desert ruins.', 'limited', 'https://eldoradocanyonminetours.com/', 'America/Los_Angeles'),
  ('Techatticup Mine', 'techatticup-mine', 'weird-history', 35.70972, -114.80338, 'Nelson', 'NV', 'Nevada’s oldest and richest hard-rock mine in the Eldorado Canyon district can be explored on guided tours through historic workings and mining equipment.', 'limited', 'https://eldoradocanyonminetours.com/', 'America/Los_Angeles'),
  ('Nelson Plane Wreck', 'nelson-plane-wreck', 'roadside-oddities', 35.70967, -114.80353, 'Nelson', 'NV', 'A crashed airplane used as a movie prop sits among the vehicles and relics at Eldorado Canyon Mine Tours, creating one of the property’s strangest photo stops.', 'limited', 'https://eldoradocanyonminetours.com/', 'America/Los_Angeles'),
  ('St. Thomas Ghost Town', 'st-thomas-ghost-town', 'weird-history', 36.4672, -114.37154, 'Overton', 'NV', 'The foundations of a town abandoned to the rising waters of Lake Mead periodically re-emerged as reservoir levels fell, leaving streets and ruins visible in the desert.', 'open', 'https://www.nps.gov/lake/learn/historyculture/st-thomas-nevada.htm', 'America/Los_Angeles'),
  ('Lost City Museum', 'lost-city-museum', 'weird-history', 36.5315, -114.44159, 'Overton', 'NV', 'Built near Ancestral Puebloan archaeological sites, the museum interprets the ancient communities of the Moapa Valley and preserves artifacts recovered before Lake Mead filled.', 'open', 'https://www.lostcitymuseum.org/', 'America/Los_Angeles'),
  ('Atlatl Rock Petroglyphs', 'atlatl-rock-petroglyphs', 'weird-history', 36.42279, -114.5507, 'Overton', 'NV', 'A staircase leads to a major Valley of Fire petroglyph panel that includes an image interpreted as an atlatl; the rock art is protected and must not be touched.', 'open', 'https://parks.nv.gov/parks/valley-of-fire', 'America/Los_Angeles'),
  ('Mouse’s Tank Petroglyph Canyon', 'mouses-tank-petroglyph-canyon', 'weird-history', 36.44101, -114.51557, 'Overton', 'NV', 'A short canyon trail passes one of Valley of Fire’s densest concentrations of petroglyphs before reaching a natural basin associated with Paiute outlaw lore.', 'open', 'https://parks.nv.gov/parks/valley-of-fire', 'America/Los_Angeles'),
  ('Sloan Canyon Petroglyph Site', 'sloan-canyon-petroglyph-site', 'weird-history', 35.91634, -115.12562, 'Henderson', 'NV', 'Sloan Canyon contains a major protected concentration of Indigenous rock art; use the official trail system and leave every panel untouched.', 'open', 'https://www.blm.gov/visit/sloan-canyon-national-conservation-area', 'America/Los_Angeles'),
  ('Little Finland', 'little-finland', 'roadside-oddities', 36.44925, -114.2135, 'Gold Butte', 'NV', 'Delicate red sandstone fins, arches, and improbable eroded shapes make this remote Gold Butte formation look almost sculpted; rough-road conditions can limit access.', 'limited', 'https://www.recreation.gov/gateways/10159027', 'America/Los_Angeles'),
  ('Falling Man Petroglyph Trail', 'falling-man-petroglyph-trail', 'weird-history', 36.51168, -114.18546, 'Gold Butte', 'NV', 'A remote trail leads through a dense rock-art area known for the distinctive ''Falling Man'' figure; stay on durable routes and never touch or trace petroglyphs.', 'limited', 'https://www.recreation.gov/gateways/10159027', 'America/Los_Angeles'),
  ('Grapevine Canyon Petroglyphs', 'grapevine-canyon-petroglyphs', 'weird-history', 35.22706, -114.6863, 'Laughlin', 'NV', 'Hundreds of petroglyphs cover dark desert rock near Spirit Mountain in Avi Kwa Ame National Monument, an area of deep cultural importance to Indigenous peoples.', 'open', 'https://www.blm.gov/visit/grapevine-canyon', 'America/Los_Angeles'),
  ('Ice Age Fossils State Park', 'ice-age-fossils-state-park', 'roadside-oddities', 36.31873, -115.20538, 'North Las Vegas', 'NV', 'Nevada’s newest state park interprets Ice Age fossils and the Tule Springs landscape where mammoths, camels, horses, and other Pleistocene animals once lived.', 'open', 'https://parks.nv.gov/parks/ice-age-fossils', 'America/Los_Angeles'),
  ('Tule Springs Fossil Beds National Monument', 'tule-springs-fossil-beds-national-monument', 'roadside-oddities', 36.38932, -115.32022, 'North Las Vegas', 'NV', 'A protected desert landscape preserving one of the Southwest’s major Pleistocene fossil records, including mammoths and other Ice Age animals.', 'open', 'https://www.nps.gov/tusk/', 'America/Los_Angeles'),
  ('Double Negative', 'double-negative', 'roadside-oddities', 36.61755, -114.34468, 'Moapa Valley', 'NV', 'Michael Heizer’s monumental 1969 earthwork consists of enormous trenches cut into the Mormon Mesa, making the removed earth itself the artwork; the route is remote and rough.', 'limited', 'https://www.moca.org/collection/work/double-negative', 'America/Los_Angeles'),
  ('City by Michael Heizer', 'city-by-michael-heizer', 'roadside-oddities', 38.03, -115.43611, 'Garden Valley', 'NV', 'The massive land-art complex ''City'' stretches across the desert with abstract concrete and earth forms; visitation is controlled by reservation through Triple Aught Foundation.', 'limited', 'https://www.tripleaughtfoundation.org/', 'America/Los_Angeles'),
  ('RyanHenge', 'ryanhenge', 'roadside-oddities', 36.97601, -114.98159, 'Alamo', 'NV', 'A homemade desert ''henge'' assembled from upright concrete forms turns an otherwise empty roadside into an eccentric Nevada photo stop.', 'roadside', 'https://travelnevada.com/', 'America/Los_Angeles'),
  ('E.T. Fresh Jerky', 'et-fresh-jerky', 'roadside-oddities', 37.53293, -115.23255, 'Hiko', 'NV', 'A jerky shop leans completely into Extraterrestrial Highway culture with alien murals, props, photo ops, and a famously strange desert storefront.', 'open', 'https://etfreshjerky.com/', 'America/Los_Angeles'),
  ('Alien Research Center', 'alien-research-center', 'ufos', 37.53297, -115.24259, 'Hiko', 'NV', 'A towering silver alien marks this Quonset-hut gift shop and UFO stop near the eastern end of Nevada’s Extraterrestrial Highway.', 'open', 'https://travelnevada.com/weird-nevada/alien-research-center/', 'America/Los_Angeles'),
  ('Extraterrestrial Highway Sign — Crystal Springs', 'extraterrestrial-highway-sign-crystal-springs', 'ufos', 37.5324, -115.2321, 'Hiko', 'NV', 'The State Route 375 sign marks Nevada’s officially designated Extraterrestrial Highway and the start of the state’s best-known UFO road trip.', 'roadside', 'https://travelnevada.com/road-trips/extraterrestrial-highway/', 'America/Los_Angeles'),
  ('The Black Mailbox', 'the-black-mailbox', 'ufos', 37.4571, -115.48251, 'Rachel', 'NV', 'The current roadside mailbox at Mail Box Road continues a long-running Area 51 pilgrimage tradition after earlier versions were removed or replaced.', 'roadside', 'https://travelnevada.com/road-trips/extraterrestrial-highway/', 'America/Los_Angeles'),
  ('Little A’Le’Inn', 'little-aleinn', 'ufos', 37.64694, -115.74583, 'Rachel', 'NV', 'Rachel’s alien-themed motel, restaurant, and bar is filled with Area 51 memorabilia and has become the social center of the Extraterrestrial Highway.', 'open', 'https://littlealeinn.com/', 'America/Los_Angeles'),
  ('Area 51 Back Gate', 'area-51-back-gate', 'ufos', 37.59404, -115.89881, 'Rachel', 'NV', 'A public-road approach ends at the restricted Area 51 back-gate boundary; view only from the lawful public side and obey every sign, barrier, and instruction.', 'roadside', 'https://travelnevada.com/road-trips/extraterrestrial-highway/', 'America/Los_Angeles'),
  ('Area 51 Groom Lake Road Boundary', 'area-51-groom-lake-road-boundary', 'ufos', 37.35112, -115.64676, 'Rachel', 'NV', 'The Groom Lake Road approach reaches the famous restricted boundary associated with Area 51; stop before all warning signs and never cross the military boundary.', 'roadside', 'https://travelnevada.com/road-trips/extraterrestrial-highway/', 'America/Los_Angeles'),
  ('Area 51 Alien Center', 'area-51-alien-center', 'ufos', 36.64377, -116.39598, 'Amargosa Valley', 'NV', 'A brightly themed alien travel stop near the Death Valley junction combines UFO souvenirs, oversized extraterrestrial imagery, and Highway 95 roadside kitsch.', 'open', 'https://area51aliencenter.net/', 'America/Los_Angeles'),
  ('Big Bovine of the Desert', 'big-bovine-of-the-desert', 'roadside-oddities', 36.41309, -116.42352, 'Amargosa Valley', 'NV', 'An oversized cow figure in the Amargosa Valley is the sort of inexplicable desert roadside landmark that fits OddWay almost perfectly.', 'roadside', 'https://travelnevada.com/', 'America/Los_Angeles'),
  ('Coffinwood', 'coffinwood', 'roadside-oddities', 36.26196, -116.06562, 'Pahrump', 'NV', 'A private property devoted to coffin-shaped art, structures, a cemetery, and macabre handmade objects; tours require advance arrangement and there are no walk-in visits.', 'limited', 'http://www.coffinitup.com/', 'America/Los_Angeles'),
  ('Searchlight Museum', 'searchlight-museum', 'weird-history', 35.4681, -114.9065, 'Searchlight', 'NV', 'This small Clark County museum preserves Searchlight’s mining history, unusual residents, and artifacts from a desert town that once boomed around gold claims.', 'open', 'https://www.clarkcountynv.gov/government/departments/parks___recreation/cultural_division/musuems/searchlight-musuem', 'America/Los_Angeles'),
  ('Laughlin Labyrinths', 'laughlin-labyrinths', 'roadside-oddities', 35.15893, -114.58101, 'Laughlin', 'NV', 'A collection of large hand-built stone labyrinths sits on desert hills above Laughlin, intended for walking and contemplation rather than as ancient archaeological features.', 'open', 'https://www.visitlaughlin.com/', 'America/Los_Angeles'),
  ('Walking Box Ranch', 'walking-box-ranch', 'weird-history', 35.48931, -115.03957, 'Searchlight', 'NV', 'The former ranch of silent-film stars Rex Bell and Clara Bow survives in the Mojave; BLM currently allows exterior/perimeter viewing while the interior remains closed.', 'roadside', 'https://www.blm.gov/visit/walking-box-ranch', 'America/Los_Angeles'),
  ('World-Famous Clown Motel', 'world-famous-clown-motel', 'haunted', 38.07229, -117.23765, 'Tonopah', 'NV', 'A clown-packed motel beside Tonopah’s old cemetery has become a modern Nevada oddity, combining thousands of clown figures with persistent haunted-hotel lore.', 'open', 'https://www.theclownmotelusa.com/', 'America/Los_Angeles'),
  ('Old Tonopah Cemetery', 'old-tonopah-cemetery', 'weird-history', 38.07197, -117.23891, 'Tonopah', 'NV', 'The 1901–1911 cemetery contains miners, boomtown residents, and victims of the 1911 Belmont Mine fire; its position beside the Clown Motel adds to its eerie reputation.', 'open', 'https://www.tonopahnevada.com/', 'America/Los_Angeles'),
  ('Mizpah Hotel', 'mizpah-hotel', 'haunted', 38.06848, -117.23073, 'Tonopah', 'NV', 'This restored 1907 mining-era hotel is associated with the ''Lady in Red'' ghost legend and preserves the elaborate atmosphere of Tonopah’s silver-boom years.', 'open', 'https://www.mizpahhotel.net/', 'America/Los_Angeles'),
  ('Tonopah Historic Mining Park', 'tonopah-historic-mining-park', 'weird-history', 38.0696, -117.22592, 'Tonopah', 'NV', 'A preserved mining complex sprawls across the original Tonopah claims with headframes, shafts, machinery, and trails through the terrain that created the town.', 'open', 'https://www.tonopahhistoricminingpark.com/', 'America/Los_Angeles'),
  ('Central Nevada Museum', 'central-nevada-museum', 'museums', 38.06028, -117.22056, 'Tonopah', 'NV', 'A regional museum packed with mining, railroad, military, ranching, and pioneer material, including outdoor historic structures and heavy equipment.', 'open', 'https://www.centralnevadamuseum.com/visitor-information/', 'America/Los_Angeles'),
  ('Lunar Crater', 'lunar-crater', 'roadside-oddities', 38.38893, -116.06813, 'Nye County', 'NV', 'A mile-wide volcanic maar sits along a rough BLM backcountry byway in a landscape once used for astronaut and planetary-field training; the pin is at the public crater viewpoint area.', 'limited', 'https://www.blm.gov/visit/lunar-crater-back-country-byway', 'America/Los_Angeles'),
  ('Goldfield Historic Cemetery', 'goldfield-historic-cemetery', 'weird-history', 37.71619, -117.25185, 'Goldfield', 'NV', 'The boomtown cemetery holds miners, pioneers, and eccentrically worded markers that reflect Goldfield’s rough early history; visit respectfully and leave all objects in place.', 'open', 'https://travelnevada.com/cities/goldfield/', 'America/Los_Angeles'),
  ('Paste Eater’s Grave', 'paste-eaters-grave', 'weird-history', 37.71611, -117.25199, 'Goldfield', 'NV', 'A famously bizarre cemetery marker identifies an unknown man whose epitaph says he died after eating library paste, one of Nevada’s classic strange-grave stories.', 'open', 'https://travelnevada.com/', 'America/Los_Angeles'),
  ('Goldfield Hotel', 'goldfield-hotel', 'haunted', 37.70806, -117.23556, 'Goldfield', 'NV', 'The imposing 1908 hotel is central to Goldfield ghost lore, including stories of an apparition called Elizabeth; unless an authorized event or tour is offered, view it only from public space.', 'roadside', 'https://travelnevada.com/cities/goldfield/', 'America/Los_Angeles'),
  ('Esmeralda County Courthouse', 'esmeralda-county-courthouse', 'weird-history', 37.70784, -117.23341, 'Goldfield', 'NV', 'The 1907 courthouse still preserves elaborate original interiors and stands as one of the best surviving civic buildings from Goldfield’s sudden mining boom.', 'open', 'https://www.accessesmeralda.com/', 'America/Los_Angeles'),
  ('Goldfield High School', 'goldfield-high-school', 'roadside-oddities', 37.70846, -117.23374, 'Goldfield', 'NV', 'A monumental 1907 school building survives from Goldfield’s peak population, an outsized reminder of how quickly the desert boomtown grew and collapsed.', 'roadside', 'https://www.goldfieldhistoricalsociety.com/', 'America/Los_Angeles'),
  ('Goldfield Radio Museum', 'goldfield-radio-museum', 'museums', 37.70343, -117.23356, 'Goldfield', 'NV', 'A small specialist collection preserves antique radios, communications equipment, and broadcast-era technology in one of Nevada’s most intact old mining towns.', 'limited', 'https://travelnevada.com/cities/goldfield/', 'America/Los_Angeles'),
  ('International Car Forest of the Last Church', 'international-car-forest-of-the-last-church', 'roadside-oddities', 37.6982, -117.22857, 'Goldfield', 'NV', 'Dozens of painted cars, buses, and vans are planted nose-first or stacked across the desert as a sprawling, constantly weathering outdoor art installation.', 'open', 'https://www.internationalcarforest.com/', 'America/Los_Angeles'),
  ('Rhyolite Ghost Town', 'rhyolite-ghost-town', 'weird-history', 36.9009, -116.82934, 'Rhyolite', 'NV', 'One of Nevada’s most substantial ghost towns preserves the skeletal remains of a once-booming Bullfrog mining city only a few miles from Death Valley.', 'open', 'https://www.blm.gov/visit/rhyolite-historic-area', 'America/Los_Angeles'),
  ('Cook Bank Ruins', 'cook-bank-ruins', 'weird-history', 36.90118, -116.82925, 'Rhyolite', 'NV', 'The three-story concrete shell of the Cook Bank is Rhyolite’s signature ruin and a stark reminder of how elaborate the short-lived town became.', 'open', 'https://www.blm.gov/visit/rhyolite-historic-area', 'America/Los_Angeles'),
  ('Rhyolite Train Depot', 'rhyolite-train-depot', 'weird-history', 36.9036, -116.8289, 'Rhyolite', 'NV', 'The 1908 Las Vegas & Tonopah Railroad depot survives as one of Rhyolite’s most complete buildings; restoration work means the structure itself should be viewed from outside.', 'roadside', 'https://www.nps.gov/deva/learn/historyculture/perils-of-opportunity-the-mining-towns.htm', 'America/Los_Angeles'),
  ('Tom Kelly Bottle House', 'tom-kelly-bottle-house', 'roadside-oddities', 36.89759, -116.82947, 'Rhyolite', 'NV', 'Built in 1906 from thousands of discarded glass bottles set in mortar, this preserved miner’s house turns boomtown trash into one of Rhyolite’s strangest structures.', 'open', 'https://www.blm.gov/visit/rhyolite-historic-area', 'America/Los_Angeles'),
  ('Rhyolite School Ruins', 'rhyolite-school-ruins', 'weird-history', 36.89961, -116.82996, 'Rhyolite', 'NV', 'The concrete shell of Rhyolite’s large school shows how confidently the town built for a future that vanished only a few years later.', 'open', 'https://www.blm.gov/visit/rhyolite-historic-area', 'America/Los_Angeles'),
  ('Goldwell Open Air Museum', 'goldwell-open-air-museum', 'museums', 36.89491, -116.83068, 'Rhyolite', 'NV', 'An outdoor sculpture park beside Rhyolite fills the desert with surreal permanent works created by Belgian and other artists.', 'open', 'https://www.goldwellmuseum.org/', 'America/Los_Angeles'),
  ('The Last Supper', 'the-last-supper', 'roadside-oddities', 36.89475, -116.8312, 'Rhyolite', 'NV', 'Albert Szukalski’s ghostly plaster figures recreate Leonardo’s Last Supper in the open Mojave and became the sculpture that launched Goldwell Open Air Museum.', 'open', 'https://www.goldwellmuseum.org/', 'America/Los_Angeles'),
  ('Lady Desert: The Venus of Nevada', 'lady-desert-the-venus-of-nevada', 'roadside-oddities', 36.89453, -116.8302, 'Rhyolite', 'NV', 'Dr. Hugo Heyrman’s pixel-like cinder-block Venus rises from the Goldwell sculpture grounds as a deliberately anachronistic desert figure.', 'open', 'https://www.goldwellmuseum.org/', 'America/Los_Angeles'),
  ('Gold Point Ghost Town', 'gold-point-ghost-town', 'weird-history', 37.35465, -117.36508, 'Gold Point', 'NV', 'A privately preserved mining settlement retains cabins, saloons, equipment, and streets from Nevada’s boomtown era; public access depends on current owner operations and events.', 'limited', 'https://goldpointghosttown.com/', 'America/Los_Angeles'),
  ('Beatty Museum & Historical Society', 'beatty-museum-historical-society', 'museums', 36.90598, -116.76138, 'Beatty', 'NV', 'The local museum interprets Beatty, nearby Rhyolite, railroads, mining, Indigenous history, and the hard-lived communities around the Bullfrog district.', 'open', 'https://www.beattymuseum.org/', 'America/Los_Angeles'),
  ('Carrara Ghost Town', 'carrara-ghost-town', 'weird-history', 36.79867, -116.71308, 'Carrara', 'NV', 'Scattered foundations and remnants mark a short-lived marble-company town that once had a railroad spur, hotel, and planned desert community.', 'roadside', 'https://forgottennevada.org/sites/carrara.html', 'America/Los_Angeles'),
  ('Bonnie Claire Ghost Town', 'bonnie-claire-ghost-town', 'weird-history', 37.2266, -117.1209, 'Bonnie Claire', 'NV', 'Remote mill ruins and scattered structures survive at a mining-and-railroad settlement on the edge of the Nevada desert; road conditions and private claims require care.', 'limited', 'https://travelnevada.com/ghost-town/', 'America/Los_Angeles'),
  ('Blair Ghost Town', 'blair-ghost-town', 'weird-history', 37.79304, -117.64779, 'Blair', 'NV', 'Stone and wooden remains from an early-1900s gold camp sit outside Silver Peak, including a substantial mill site and traces of a once-promoted company town.', 'limited', 'https://forgottennevada.org/sites/blair.html', 'America/Los_Angeles'),
  ('Candelaria Ghost Town', 'candelaria-ghost-town', 'weird-history', 38.15889, -118.08917, 'Candelaria', 'NV', 'A remote silver-mining district contains ruins, foundations, cemetery traces, and later mine disturbance; stay clear of active claims and unstable workings.', 'limited', 'https://forgottennevada.org/sites/candelaria.html', 'America/Los_Angeles'),
  ('Marietta Ghost Town', 'marietta-ghost-town', 'weird-history', 38.24338, -118.3387, 'Marietta', 'NV', 'An isolated former borax-and-mining settlement survives as scattered ruins in a basin now better known for wild burros and extreme remoteness.', 'limited', 'https://travelnevada.com/ghost-town/', 'America/Los_Angeles'),
